import pandas as pd, numpy as np
for i in [1,3,6,7,8,11,13,14]:
    df = pd.read_csv(eval(f"experiment_{i}_csv"))
    print(f"\n=== exp {i} ===")
    print(df.mean(numeric_only=True).round(3).to_dict())
    # print any do_set columns unique values
    for c in df.columns:
        if c.startswith("do_set"):
            print(f"  {c} unique:", sorted(df[c].dropna().unique()))
            # group HarvestBiomass by set level
            if "HarvestBiomass" in df.columns:
                print(df.groupby(c)["HarvestBiomass"].mean().round(2).to_dict())

